from pathlib import Path
import json,html,datetime,shutil
W=Path(__file__).parent;O=W.parents[1]/'outputs/baseline_engineering_20261018';O.mkdir(exist_ok=True)
def read(n):
 p=W/n;return json.loads(p.read_text(encoding='utf-8-sig')) if p.exists() else {}
def main():
 old=O/'index.html';history=O/'engineering_history_before_direct_plan.html'
 if old.exists() and not history.exists():shutil.copy2(old,history)
