 plan=dict(updated_at=now,experiment_A=dict(target='matched five GN1130K + fresh instances30K',GN11_step=step,direct_queue=direct,interstage_ablations=False),
  experiment_B=dict(target='all visible vehicles including parked, firststage30K only',preparation=allstate,full_RGB_retained=True,initialization_mask_identity_sets_must_match=True,parallel_only_after_memory_admission=True),
  report=dict(full_frame=True,ROI=False,frame_ids=list(range(89,138)),synchronized=True,all_vehicle_delete_required=True),human_verdict=None)
