 for n in ['direct_plan.json','direct_queue_status.json','all_actor_queue_status.json','direct_CPU_gate.json','direct_plan_cancellation_receipt.json','all_vehicle_coverage.json']:
  if (W/n).exists():shutil.copy2(W/n,O/n)
 if (W/'all_vehicle_raw128.png').exists():shutil.copy2(W/'all_vehicle_raw128.png',O/'all_vehicle_raw128.png')
 svg='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 295" role="img" aria-label="两条实验的数据流"><defs><marker id="a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#97bdda"/></marker></defs><g fill="#203c52" stroke="#749bb8"><rect x="10" y="70" width="190" height="150" rx="8"/><rect x="270" y="20" width="215" height="95" rx="8"/><rect x="550" y="20" width="220" height="95" rx="8"/><rect x="270" y="175" width="215" height="95" rx="8"/><rect x="550" y="175" width="220" height="95" rx="8"/><rect x="845" y="70" width="245" height="150" rx="8"/></g><g stroke="#97bdda" fill="none" marker-end="url(#a)"><path d="M200 115H230V67H270M200 175H230V222H270M485 67H550M485 222H550M770 67H810V115H845M770 222H810V175H845"/></g><g fill="#e9f4fc" font-family="sans-serif" font-size="18" text-anchor="middle"><text x="105" y="115">完整49帧 RGB</text><text x="105" y="150">真实 LiDAR / 相机</text><text x="105" y="185">全部原数据保留</text><text x="377" y="57">A：五身份 GN11 30K</text><text x="377" y="85">掩码＋初始化同批身份</text><text x="660" y="57">五身份实例 30K</text><text x="660" y="85">直接衔接，无中间消融</text><text x="377" y="211">B：全部车辆输入补齐</text><text x="377" y="239">运动＋停驶，同一身份表</text><text x="660" y="211">全车辆第一阶段 30K</text><text x="660" y="239">静态街景＋动态集合</text><text x="967" y="112">完整画面同步播放器</text><text x="967" y="148">动态 / 静态 / 逐ID删除</text><text x="967" y="184">删除全部车辆后验收</text></g></svg>'''
 (O/'direct_architecture.svg').write_text(svg,encoding='utf-8')
 d=html.escape(direct.get('state','队列登记中'));a=html.escape(allstate.get('state','输入补齐中'))
 page=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>R15 两条实验：完整画面交付</title><style>body{{background:#0b1520;color:#e6f1fa;font:16px/1.7 system-ui,Microsoft YaHei;margin:0}}main{{max-width:1180px;margin:auto;padding:28px}}a{{color:#87d2ff}}section{{background:#132637;padding:20px;border-radius:10px;margin:18px 0}}table{{border-collapse:collapse;width:100%}}th,td{{border:1px solid #38566d;text-align:left;padding:12px}}img{{width:100%;height:auto}}code{{overflow-wrap:anywhere;color:#bfe2f6}}.muted{{color:#b5c9d9}}h1{{font-size:28px}}</style><main><h1>两条实验按完整画面验收</h1><p>状态快照：{now}（新加坡时间）。正式训练结果完成后再填入最终播放器。</p><img src="direct_architecture.svg" alt="完整RGB输入，经五身份两阶段和全车辆单阶段训练，输出同步分支删除对照"><section><table><tr><th>实验</th><th>训练安排</th><th>当前状态</th></tr><tr><td>A：同一批五身份</td><td>GN11 30K → 新实例30K<br>取消两阶段之间的消融</td><td>GN11 {step}/30000<br><code>{d}</code></td></tr><tr><td>B：所有可见车辆，包含停驶车辆</td><td>补齐掩码、真实初始化与身份表 → 第一阶段30K<br>本轮不跑第二阶段</td><td><code>{a}</code></td></tr></table><p>显存准入通过才并行；根据实际峰值和点数评估，必要时排队。所有历史检查点保留。</p></section><section><h2>报告显示整个画面</h2><p>统一49帧时间轴，支持播放、暂停、逐帧拖动。每辆车可查看完整场景、动态分支、静态分支、独立资产和删除前后。最终新增“删除全部车辆”页面。视频和显示窗口均使用完整画面，无ROI裁剪、无局部放大。</p><p><a href="../identity_comparison_20261018/index.html">已有历史对照播放器（已改为完整画面）</a> · <a href="engineering_history_before_direct_plan.html">此前工程证据与更正记录</a></p></section><section><h2>全车辆覆盖正在补齐</h2><p>49帧标注共包含45条车辆轨迹，其中32条按中位速度低于0.5 m/s计为停驶；20条在本相机中有投影LiDAR证据。这些数字不等于完整可见车辆清单。此前缓存只对部分车辆完成了身份关联，正在使用原始1920×1280图像重新生成全车辆提议，再逐帧核对覆盖与初始化。</p><img src="all_vehicle_raw128.png" alt="raw128完整观测与旧缓存车辆提议全图对照"><p class="muted">图为旧缓存覆盖诊断，并非新30K结果。稀疏LiDAR命中率不能替代像素级与视觉检查；有遗漏的车辆不能直接标为背景。</p></section><section><h2>验收标准</h2><p>检查车辆是否残留在静态层、逐身份删除是否干净、全部删除后道路是否连续。跨帧看见过的道路可由观测约束；始终被遮挡的部分没有真实背景监督，本次基础30K不会自动增加生成补全。没有配对干净背景真值时，明确标注缺口。</p><p>第二阶段已接回原孤立动态α100，并保留逐身份可见贡献监督；相机无放回采样、SH间隔及空间增密／剪枝调用已经登记。CPU空间参考9项及采样恢复检查通过；实际GPU和最终资产质量仍待训练与评估。刚体表示没有PVG时间分裂，保留第一阶段SGCM结果。原生增密后重置屏幕半径的顺序也被保留，不能声称它提供持续的大投影点保证。</p></section><p><a href="direct_plan.json">实验登记</a> · <a href="direct_CPU_gate.json">CPU检查</a> · <a href="direct_plan_cancellation_receipt.json">中间消融取消凭据</a></p></main></html>'''
 page=page.replace('正在使用原始1920×1280图像重新生成全车辆提议，再逐帧核对覆盖与初始化。','已使用原始1920×1280图像完成全车辆49帧原生推理，峰值显存约11.27 GiB；目前正在补齐远处车辆的覆盖、身份关联与真实初始化。')
